sys_script.script:
(function executeRule(current, previous) {

    var values = "";
    var columns = [
        'role_sin',
        'yakushoku_3',
        'kenmu1_kyuu',
        'kenmu3_sin',
        'kenmu1_sin',
        'tyokkan_kyuu',
        'naiji_yotei',
        'grade_sin',
        'fukusuu_flg',
        'genyakushoku_2',
        'vu_sin',
        'shumu_sin',
        'reason',
        'bikou',
        'genyakushoku_1',
        'kimuti_kyuu',
        'kenmu2_kyuu',
        'kimuti_sin',
        'tantoumei',
        'naiji_umu',
        'yakui_kyuu',
        'kenmu5_kyuu',
        'yakushoku_1',
        'number',
        'tyokkann_sin',
        'ninmen',
        'kenmu2_sin',
        'ryou',
        'sinshozoku',
        'type',
        'grade_kyuu',
        'vu_kyuu',
        'jissibi',
        'role_kyuu',
        'yakui_sin',
        'kenmu4_kyuu',
        'kazoku',
        'name',
        'genyakushoku_4',
        'kenmu4_sin',
        'bikou_gen',
        'kenmu3_kyuu',
        'hatureibi',
        'sakusei_kaisuu',
        'genyakushoku_3',
        'yakushoku_4',
        'juukyo',
        'yakushoku_2',
        'shumu_kyuu',
		'kenmu_number'
    ];


    var gr = new GlideRecord('x_1882833_organi_0_meisai');
    gr.addQuery('oya_meisai', current.oya_meisai);
    gr.addQuery('sinsei_number', current.sinsei_number);
    gr.query();

    while (gr.next()) {
        for (var i = 0; i < columns.length; i++) {
            var col = columns[i];

            if (!gr.isValidField(col)) {
                continue;
            }
            values = values + ',' + gr.getDisplayValue(col);
        }
    }

    values = values
        .split(',')
        .filter(function(v) {
            return v && v !== 'null' && v !== 'true' && v !== 'false';
        })
        .join(',');

    gr = new GlideRecord('x_1882833_organi_0_meisai');
    gr.addQuery('oya_meisai', current.oya_meisai);
    gr.addQuery('sinsei_number', current.sinsei_number);
    gr.query();

    while (gr.next()) {
        gr.data = values;
        gr.update();
    }

})(current, previous);
